<script lang="ts">
  import {onMount,onDestroy} from 'svelte';
  import type {FieldDefinition} from '../../api/domain';
  import {loadWorkflow,saveWorkflow,type WorkflowConfiguration,type WorkflowDefinition,type ProcessKind} from '../../api/workflows';
  import {workflowKindNames,workflowTemplate} from '../../util/workflowTemplates';
  import {requestConfirmation} from '../../confirmation';
  let {moduleUid,moduleName,fields,dirty=$bindable(false)}:{moduleUid:string;moduleName:string;fields:FieldDefinition[];dirty?:boolean}=$props();
  let configuration=$state<WorkflowConfiguration|null>(null);let draft=$state<WorkflowDefinition>(workflowTemplate('custom'));let saved=$state('');
  let loading=$state(true);let busy=$state(false);let error=$state('');let notice=$state('');let confirmExisting=$state(false);let controller:AbortController|undefined;
  const publicFields=$derived(fields.filter(f=>f.active&&(!f.config.access_scope||f.config.access_scope==='module')));
  const titleFields=$derived(publicFields.filter(f=>['text','long_text','auto_number','integer','date','select'].includes(f.field_type)));
  const requirementFields=$derived(publicFields.filter(f=>!['formula','lookup','rollup'].includes(f.field_type)));
  const previouslyConfigured=$derived(!!configuration?.definition.states.length);
  $effect(()=>{dirty=!!saved&&JSON.stringify(draft)!==saved;});
  onMount(()=>void reload());onDestroy(()=>controller?.abort());
  async function reload(){controller?.abort();controller=new AbortController();loading=true;error='';try{const result=await loadWorkflow(moduleUid,controller.signal);configuration=result;draft=result.definition.states.length?structuredClone(result.definition):workflowTemplate('custom');saved=JSON.stringify(draft);confirmExisting=false;}catch(reason){if(!controller?.signal.aborted)error=reason instanceof Error?reason.message:String(reason);}finally{loading=false;}}
  async function chooseTemplate(kind:ProcessKind){if(previouslyConfigured)return;if(dirty&&!await requestConfirmation({title:'Replace this unsaved process draft?',description:'No module fields or records will be created. Your unsaved stage and action settings will be replaced.',confirmLabel:'Use draft',tone:'primary'}))return;draft=workflowTemplate(kind);error='';notice='Draft loaded. Review stages, permitted actions and required fields, then explicitly enable and save.';}
  async function save(event:SubmitEvent){event.preventDefault();if(busy||!configuration)return;busy=true;error='';notice='';try{const result=await saveWorkflow(moduleUid,configuration.revision,$state.snapshot(draft),confirmExisting);configuration={...result,existing_records:configuration.existing_records};draft=structuredClone(result.definition);saved=JSON.stringify(draft);notice=draft.enabled?'Process saved and enabled. Open this module’s Work queue to test it.':'Process configuration saved, but disabled. Records continue to work normally.';}catch(reason){error=reason instanceof Error?reason.message:String(reason);}finally{busy=false;}}
  function nextKey(prefix:string,keys:string[]){let n=1;while(keys.includes(`${prefix}_${n}`))n++;return `${prefix}_${n}`;}
  function addState(){const key=nextKey('stage',draft.states.map(s=>s.key));draft.states.push({key,name:`Stage ${draft.states.length+1}`});}
  function addAction(){const key=nextKey('action',draft.actions.map(a=>a.key));draft.actions.push({key,name:'New action',from:draft.initial_state,to:draft.states.find(s=>s.key!==draft.initial_state)?.key||'',access_levels:[0,1,2],creator_policy:'any',required_fields:[],note_required:false});}
</script>
<section class="panel process-admin" aria-label="Module workflow configuration">
  <header><p class="eyebrow">Module · {moduleName}</p><h2>Process & actions</h2><p>Give records a process: stages, permitted actions, required information and an auditable decision history. Form rules still control the fields inside a form.</p></header>
  {#if loading}<p role="status">Loading process configuration…</p>{:else if !configuration}<div class="notice error" role="alert">{error}<button class="button" type="button" onclick={reload}>Retry</button></div>{:else}
  <form onsubmit={save} aria-label="Configure module process">
    {#if !previouslyConfigured}<fieldset class="process-start"><legend>1 · Start with a draft</legend><p>These are editable examples, not complete ERP or accounting products. They do not add fields, records or modules.</p><div class="template-grid">{#each Object.entries(workflowKindNames) as [kind,name]}<button type="button" class="button" class:chosen={draft.kind===kind} aria-pressed={draft.kind===kind} disabled={busy} onclick={()=>void chooseTemplate(kind as ProcessKind)}>{name}</button>{/each}</div></fieldset>{/if}
    <fieldset><legend>{previouslyConfigured?'Process settings':'2 · Review process settings'}</legend><div class="settings-grid"><label>Process name<input required maxlength="120" bind:value={draft.name}/></label><label>Purpose<select bind:value={draft.kind}>{#each Object.entries(workflowKindNames) as [kind,name]}<option value={kind}>{name}</option>{/each}</select></label><label>Queue title field<select bind:value={draft.title_field}><option value="">Record identifier</option>{#each titleFields as f}<option value={f.key}>{f.label}</option>{/each}</select></label><label>Starting stage<select bind:value={draft.initial_state} disabled={previouslyConfigured}>{#each draft.states as stage}<option value={stage.key}>{stage.name}</option>{/each}</select></label></div>
      <label class="checkbox"><input type="checkbox" bind:checked={draft.restart_on_edit}/> Require the process to restart after record edits</label><p class="help">Recommended for approvals. Editing values, changing attachments or restoring a record version returns it to the starting stage. Earlier decisions remain in history and apply only to their saved revision.</p>
      {#if draft.kind==='accounting'}<p class="notice">Expense approval only: this does not post journal entries, enforce double-entry accounting, calculate tax or replace an accounting ledger. Decimal record fields are not an exact-money ledger.</p>{/if}
    </fieldset>
    <fieldset><legend>Stages</legend><p class="help">Labels can change. Saved stage keys stay fixed so existing records keep their meaning.</p><div class="stages">{#each draft.states as stage}<div><label>Stage name<input required maxlength="120" bind:value={stage.name}/></label><small>Key: {stage.key}{stage.key===draft.initial_state?' · Starting stage':''}</small></div>{/each}</div><button type="button" class="button small" disabled={busy||draft.states.length>=24} onclick={addState}>Add stage</button></fieldset>
    <fieldset><legend>Actions</legend><p class="help">An action moves a record between two stages. Account-level permission never overrides module Edit permission or creator-only record access.</p>
      <div class="actions">{#each draft.actions as action,index (action.key)}<article class="action-card"><header><h3>{action.name||'New action'}</h3><button type="button" class="button small" disabled={busy} onclick={()=>draft.actions=draft.actions.filter((_,i)=>i!==index)} aria-label={`Remove ${action.name}`}>Remove action</button></header><div class="settings-grid"><label>Action name<input required maxlength="120" bind:value={action.name}/></label><label>From stage<select bind:value={action.from}>{#each draft.states as s}<option value={s.key}>{s.name}</option>{/each}</select></label><label>To stage<select bind:value={action.to}>{#each draft.states as s}<option value={s.key}>{s.name}</option>{/each}</select></label><label>Who may act?<select bind:value={action.creator_policy}><option value="any">Any permitted editor</option><option value="creator">Only the record creator</option><option value="not_creator">A different person from the creator</option></select></label></div>
        <fieldset class="choices"><legend>Permitted account levels</legend>{#each ['Administrator','Manager','Editor','Viewer'] as role,level}<label class="checkbox"><input type="checkbox" bind:group={action.access_levels} value={level}/>{role}</label>{/each}</fieldset><p class="help">A different reviewer requires known record ownership. Even an administrator must satisfy this action’s configured creator policy.</p>
        <details><summary>Required fields · {action.required_fields.length} selected</summary><div class="choices">{#each requirementFields as field}<label class="checkbox"><input type="checkbox" bind:group={action.required_fields} value={field.key}/>{field.label}</label>{/each}</div>{#if !requirementFields.length}<p>Add module-visible fields in Fields first.</p>{/if}</details><label class="checkbox"><input type="checkbox" bind:checked={action.note_required}/> Require an action note</label><small class="help">Action key: {action.key}. Notes are visible to people who can view the record.</small></article>{/each}</div><button type="button" class="button" disabled={busy||draft.actions.length>=64||draft.states.length<2} onclick={addAction}>Add action</button>
    </fieldset>
    <fieldset><legend>Enablement</legend><label class="checkbox"><input type="checkbox" bind:checked={draft.enabled}/> Enable this process for {moduleName}</label><p class="help">Disabled processes keep their configuration and history, but no new actions can be taken. Records and existing modules are never deleted.</p>{#if draft.enabled&&!configuration.definition.enabled&&(configuration.existing_records||0)>0}<label class="checkbox"><input type="checkbox" bind:checked={confirmExisting}/> Apply to the {configuration.existing_records} existing records. Records without workflow history start at {draft.states.find(s=>s.key===draft.initial_state)?.name}.</label>{/if}</fieldset>
    {#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
    <footer><span>{dirty?'Unsaved process changes':`Saved configuration revision ${configuration.revision}`}</span><button type="button" class="button" disabled={busy} onclick={async()=>{if(!dirty||await requestConfirmation({title:'Discard process changes?',description:'Reload the saved configuration. Your unsaved process draft will be lost.',confirmLabel:'Discard',tone:'danger'}))await reload();}}>Reload saved</button><button class="button primary" disabled={busy||!dirty}>{busy?'Saving process…':'Save process'}</button></footer>
  </form>{/if}
</section>
<style>
  .process-admin{max-width:78rem}.process-admin header p{color:var(--muted)}h2{margin:.2rem 0}form{display:grid;gap:1.1rem}fieldset{min-width:0;border:1px solid var(--line);border-radius:.6rem;padding:1rem;display:grid;gap:.75rem}legend{font-weight:650;padding:0 .4rem}.settings-grid,.template-grid,.stages{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,15rem),1fr));gap:.85rem}label:not(.checkbox){display:grid;gap:.4rem;min-width:0}input,select{width:100%;min-width:0}.checkbox{display:flex;align-items:start;gap:.5rem;line-height:1.5}.checkbox input{width:auto;margin-top:.25rem;flex-shrink:0}.help,small{color:var(--muted);font-size:.875rem;line-height:1.6;overflow-wrap:anywhere}.help{margin:0}.choices{display:flex;flex-wrap:wrap;gap:.75rem 1.2rem}.choices legend{font-size:.875rem}.actions{display:grid;gap:1rem}.action-card{min-width:0;border:1px solid var(--line);border-radius:.5rem;padding:1rem;display:grid;gap:.9rem;background:var(--surface-2)}.action-card header,footer{display:flex;align-items:center;gap:.75rem;flex-wrap:wrap;justify-content:space-between}.action-card h3{font-size:1rem;margin:0}details summary{cursor:pointer;padding:.3rem 0}details .choices{padding:.6rem 0}.chosen{outline:2px solid var(--accent,#3768a6);outline-offset:1px}footer{border-top:1px solid var(--line);padding-top:1rem}footer span{color:var(--muted);flex:1;min-width:10rem}.stages>div{display:grid;gap:.4rem}@media(max-width:600px){fieldset,.action-card{padding:.75rem}footer button{flex:1}.template-grid{grid-template-columns:1fr}}
</style>
